@icontract.ensure(lambda return_objects, logging, result: not (return_objects and logging) or isinstance(result[0], (dict, list, str, int, float, bool, type(None))), "When both return_objects and logging are True, first element must be a valid JSON type")
@icontract.ensure(lambda return_objects, logging, result: (return_objects or logging) or (isinstance(result, str) and len(result) >= 0), "When return_objects is False and logging is False, result must be a non-None string")

@icontract.ensure(lambda logging, result: not logging or isinstance(result, tuple), "When logging is True, result must be a tuple")
